-- BPGC / food, migration 1. Paste the entire script into the SQL Editor of
-- project jbzbnidtcmywmudfjipv and run once. Safe to rerun without deleting likes.
-- This prepares shared item likes and read-only menu data. It does NOT turn the
-- admin preview into a real admin system. No service-role key belongs in browser code.
begin;
create table if not exists public.food_items (
  id text primary key,
  outlet text not null,
  category text not null,
  name text not null,
  price numeric(10,2) check (price is null or price >= 0),
  active boolean not null default true
);
create table if not exists public.item_likes (
  item_id text not null references public.food_items(id) on delete restrict,
  user_id uuid not null references auth.users(id) on delete cascade,
  created_at timestamptz not null default now(),
  primary key(item_id,user_id)
);
create index if not exists item_likes_user_id_idx on public.item_likes(user_id);
-- Reserved for a future secure admin flow. No browser role writes are granted.
create table if not exists public.app_roles (
  user_id uuid primary key references auth.users(id) on delete cascade,
  role text not null check(role in ('admin','super_admin')),
  granted_by uuid references auth.users(id),
  granted_at timestamptz not null default now()
);
alter table public.food_items enable row level security;
alter table public.item_likes enable row level security;
alter table public.app_roles enable row level security;
revoke all on public.item_likes from anon, authenticated;
revoke all on public.app_roles from anon, authenticated;
revoke all on public.food_items from anon, authenticated;
grant select on public.food_items to anon, authenticated;
drop policy if exists food_items_read on public.food_items;
create policy food_items_read on public.food_items for select to anon, authenticated using (active);
-- Likes have no direct client table policies; writes go through checked RPCs.
create or replace function public.heart_item(p_item_id text,p_liked boolean)
returns void language plpgsql security definer set search_path = '' as $$
declare actor uuid := auth.uid();
begin
  if actor is null then raise exception 'Sign in first' using errcode='28000'; end if;
  if p_item_id is null or length(p_item_id)>120 or not exists
    (select 1 from public.food_items where id=p_item_id and active) then
      raise exception 'Unknown item' using errcode='22023';
  end if;
  if p_liked then
    insert into public.item_likes(item_id,user_id) values(p_item_id,actor)
    on conflict do nothing;
  else
    delete from public.item_likes where item_id=p_item_id and user_id=actor;
  end if;
end $$;
create or replace function public.heart_counts()
returns table(item_id text,hearts bigint)
language sql stable security definer set search_path = '' as $$
 select l.item_id,count(*)::bigint as hearts from public.item_likes l
 join public.food_items i on i.id=l.item_id and i.active
 group by l.item_id
$$;
create or replace function public.my_hearts()
returns table(item_id text)
language sql stable security definer set search_path = '' as $$
 select l.item_id from public.item_likes l where l.user_id=auth.uid()
$$;
revoke all on function public.heart_item(text,boolean) from public,anon;
revoke all on function public.heart_counts() from public,anon;
revoke all on function public.my_hearts() from public,anon;
grant execute on function public.heart_item(text,boolean) to authenticated;
grant execute on function public.heart_counts() to authenticated;
grant execute on function public.my_hearts() to authenticated;
-- Seed catalog IDs match the app's existing stable IDs. Existing likes are retained.
insert into public.food_items(id,outlet,category,name,price)
select r.id,r.outlet,r.category,r.name,r.price
from jsonb_to_recordset($menu$
